INSERT INTO [dbo].[GEN_FILE] ([Gen_File_Id], [File_Type_Id], [File_Name], [Title], [Name], [File_Size], [Doc_Num], [Comments], [Description], [Short_Name], [Publish_Date], [Doc_Version], [Summary], [Source_Type], [Data], [Is_Uploaded]) VALUES (5062, 28, 'ACET Pre 10.acet', '(no title)', NULL, 6201, 'NONE', NULL, NULL, '(no short name)', NULL, NULL, NULL, NULL, NULL, 1)
INSERT INTO [dbo].[GEN_FILE] ([Gen_File_Id], [File_Type_Id], [File_Name], [Title], [Name], [File_Size], [Doc_Num], [Comments], [Description], [Short_Name], [Publish_Date], [Doc_Version], [Summary], [Source_Type], [Data], [Is_Uploaded]) VALUES (5063, 31, 'mdse-nist-sp1800-22-draft final.pdf', 'DRAFT NIST SP 1800-22 Mobile Device Security: Bring Your Own Device (BYOD) March 2021', 'DRAFT Mobile Device Security: Bring Your Own Device (BYOD) March 2021', 15966721, 'NONE', 'DRAFT VERSION March 2021', 'Allowing employees to use their personal mobile devices for work-related activities is commonly known as a bring your own device (BYOD) deployment.', 'DRAFT NIST SP 1800-22 March 2021', NULL, NULL, 'Many organizations now provide employees the flexibility to use their personal mobile devices to perform work-related activities. An ineffectively secured personal mobile device could expose an organization or employee to data loss or a privacy compromise. Ensuring that an organization’s data is protected when it is accessed from personal devices poses unique challenges and threats. 
INSERT INTO [dbo].[GEN_FILE] ([Gen_File_Id], [File_Type_Id], [File_Name], [Title], [Name], [File_Size], [Doc_Num], [Comments], [Description], [Short_Name], [Publish_Date], [Doc_Version], [Summary], [Source_Type], [Data], [Is_Uploaded]) VALUES (5064, NULL, 'merge.svg', 'Merge SVG document', 'merge svg name', 1078, 'NONE', 'merge svg description', 'merge svg description', 'merge svg short name', NULL, NULL, 'merge svg summary', NULL, NULL, 1)
INSERT INTO [dbo].[GEN_FILE] ([Gen_File_Id], [File_Type_Id], [File_Name], [Title], [Name], [File_Size], [Doc_Num], [Comments], [Description], [Short_Name], [Publish_Date], [Doc_Version], [Summary], [Source_Type], [Data], [Is_Uploaded]) VALUES (5065, 31, 'TSA pipeline_security_guidelines 2019.pdf', 'TSA Pipeline Security Guidelines April 2019', 'TSA Pipeline Security Guidelines April 2019', 957019, 'NONE', NULL, 'These guidelines are applicable to operational natural gas and hazardous liquid transmission pipeline systems, natural gas distribution pipeline systems, and liquefied natural gas facility operators.', 'TSA Pipeline 2019', NULL, NULL, 'Under the provisions of the Aviation and Transportation Security Act (Public Law 107-71), the Transportation Security Administration (TSA) was established on November 19, 2001 with responsibility for civil aviation security and “security responsibilities over other modes of transportation that are exercised by the Department of Transportation.” On September 8, 2002, TSA initiated its pipeline security efforts. Those responsibilities now reside within the Office of Security Policy and Industry Engagement’s Surface Division.', NULL, NULL, 0)
