INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003618, 'C800_53_R5_V2', 216, 'Does the organization implement the security design principle of clear abstractions via simple, well-defined interfaces and functions and a consistent view of how data is managed?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003619, 'C800_53_R5_V2', 217, 'Does the organization implement the security design principle of least common mechanism via minimizing the amount of mechanism common to one user and depended on by all users?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003620, 'C800_53_R5_V2', 218, 'Does the organization implement the security design principle of modularity and layering to manage system complexity?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003621, 'C800_53_R5_V2', 219, 'Does the organization implement the security design principle of principle of partially ordered dependencies to increase simplicity and coherency of the system design?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003622, 'C800_53_R5_V2', 220, 'Does the organization implement the security design principle of efficiently mediated access by ensuring that policy enforcement mechanisms utilize the least common mechanism available while satisfying stakeholder requirements?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003623, 'C800_53_R5_V2', 221, 'Does the organization implement the security design principle of minimized sharing via ensuring that no computer resource is shared between system components unless absolutely necessary?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003624, 'C800_53_R5_V2', 222, 'Does the organization implement the security design principle of reduced complexity by ensuring that the system design is as simple and small as possible?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003625, 'C800_53_R5_V2', 223, 'Does the organization implement the security design principle of secure evolvability by ensuring that a system is developed to facilitate the maintenance of its security properties when there are changes to the systems'' structure, interfaces, interconnections, functionality, or configuration?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003626, 'C800_53_R5_V2', 224, 'Does the organization implement the security design principle of trusted components by ensuring that a component is trustworthy to at least a level commensurate with the security dependencies it supports?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003627, 'C800_53_R5_V2', 225, 'Does the organization implement the security design principle of hierarchical trust by ensuring that the security dependencies in a system will form a partial ordering if they preserve the principle of trusted components?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003628, 'C800_53_R5_V2', 226, 'Does the organization implement the security design principle of inverse modification threshold by ensuring that the degree of protection provided to a component is commensurate with its trustworthiness?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003629, 'C800_53_R5_V2', 227, 'Does the organization implement the security design principle of hierarchical protection by ensuring that a component need not be protected by more trustworthy components?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003630, 'C800_53_R5_V2', 228, 'Does the organization implement the security design principle of minimized security elements by ensuring that the system does not have extraneous trusted components?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003631, 'C800_53_R5_V2', 229, 'Does the organization implement the security design principle of least privilege by ensuring that each system component is allocated sufficient privileges to accomplish specified function but no more?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003632, 'C800_53_R5_V2', 230, 'Does the organization implement the security design principle of predicate permission by ensuring that system designers consider multiple authorized entities to provide consent before a highly critical operation or access to highly sensitive data, information, or resources is allowed to proceed?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003633, 'C800_53_R5_V2', 231, 'Does the organization implement the security design principle of self-reliant trustworthiness by ensuring that systems minimize their reliance on other systems for their own trustworthiness?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003634, 'C800_53_R5_V2', 232, 'Does the organization implement the security design principle of secure distributed composition by ensuring that the composition of distributed components that enforce the same system security policy result in a system that enforces that policy at least as well as the individual components do?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003635, 'C800_53_R5_V2', 233, 'Does the organization implement the security design principle of trusted communications channels by ensuring that when composing a system where there is a potential threat to communications between components each communication channel is trustworthy to a level commensurate with the security dependencies it supports?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003636, 'C800_53_R5_V2', 234, 'Does the organization implement the security design principle of continuous protection by ensuring that components and data used to enforce the security policy have uninterrupted protection that is consistent with the security policy and the security architecture assumptions?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003637, 'C800_53_R5_V2', 235, 'Does the organization implement the security design principle of secure metadata management by ensuring that metadata are “first class” objects with respect to security policy when the policy requires either complete protection of information or that the security subsystem be self-protecting?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003638, 'C800_53_R5_V2', 236, 'Does the organization implement the security design principle of self-analysis by ensuring that a system component is able to assess its internal state and functionality to a limited extent at various stages of execution, and that this self-analysis capability is commensurate with the level of trustworthiness invested in the system?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003639, 'C800_53_R5_V2', 237, 'Does the organization implement the security design principle of accountability and traceability by ensuring that it''s possible to trace security-relevant actions to the entity on whose behalf the action is being taken?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003640, 'C800_53_R5_V2', 238, 'Does the organization implement the security design principle of secure defaults by ensuring that the default configuration of a system reflects a restrictive and conservative enforcement of security policy?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003641, 'C800_53_R5_V2', 239, 'Does the organization implement the security design principle of secure failure and recovery by ensuring that neither a failure in a system function or mechanism nor any recovery action in response to failure leads to a violation of security policy?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003642, 'C800_53_R5_V2', 240, 'Does the organization implement the security design principle of economic security by ensuring that security mechanisms are not costlier than the potential damage that could occur from a security breach?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
