INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003644, 'C800_53_R5_V2', 242, 'Does the organization implement the security design principle of human factored security by ensuring that the user interface for security functions and supporting services is intuitive, user-friendly, and provides feedback for user actions that affect such policy and its enforcement?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
INSERT INTO [dbo].[NEW_QUESTION] ([Question_Id], [Std_Ref], [Std_Ref_Number], [Simple_Question], [Universal_Sal_Level], [Weight], [Question_Group_Id], [Question_Group_Number], [Original_Set_Name], [Ranking], [Heading_Pair_Id]) VALUES (1003645, 'C800_53_R5_V2', 243, 'Does the organization implement the security design principle of acceptable security by ensuring that  the level of privacy and performance that the system provides is consistent with the users’ expectations?', 'L', 0, NULL, NULL, 'C800_53_R5_V2', NULL, 4724)
