UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]='a. Generate error messages that provide information necessary for corrective actions without revealing information that could be exploited; andb. Reveal error messages only to [Assignment: organization-defined personnel or roles].' WHERE [Requirement_Id] = 30989
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]='a. Determine mean time to failure (MTTF) for the following system components in specific environments of operation: [Assignment: organization-defined system components]; andb. Provide substitute system components and a means to exchange active and standby components in accordance with the following criteria: [Assignment: organization-defined MTTF substitution criteria].' WHERE [Requirement_Id] = 30994
